export const envelope = [32, 64, 32];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 8;
  const cx = 16;
  const cz = 16;

  // Palette references
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const mossBlock = "minecraft:moss_block";
  const mossCarpet = "minecraft:moss_carpet";
  const hangingRoots = "minecraft:hanging_roots";
  const leaves = "minecraft:spruce_leaves[persistent=true]";

  // 3D Voxel Grid: 0 = empty
  const grid = new Array(sizeX);
  for (let x = 0; x < sizeX; x++) {
    grid[x] = new Array(sizeY);
    for (let y = 0; y < sizeY; y++) {
      grid[x][y] = new Array(sizeZ).fill(null);
    }
  }

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      grid[x][y][z] = block;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      return grid[x][y][z];
    }
    return null;
  }

  function angDiff(a, b) {
    let d = Math.abs(a - b) % (Math.PI * 2);
    return d > Math.PI ? Math.PI * 2 - d : d;
  }

  // Trunk taper profile relative to seat plane
  function getTrunkRadius(yRel) {
    if (yRel < 0) return 5.2 + Math.min(3.5, -yRel * 0.45);
    if (yRel < 6) return 5.2 - (yRel / 6) * 1.0;
    if (yRel < 20) return 4.2 - ((yRel - 6) / 14) * 1.1;
    if (yRel < 36) return 3.1 - ((yRel - 20) / 16) * 0.9;
    return Math.max(1.2, 2.2 - ((yRel - 36) / 16) * 1.0);
  }

  // 6 Massive flared buttress roots radiating outward (leaving North open for doorway)
  const buttresses = [
    { angle: 0.15, ext: 7.8, h: 14 }, // East
    { angle: 1.15, ext: 8.8, h: 16 }, // South-East
    { angle: 2.10, ext: 8.2, h: 15 }, // South-West
    { angle: 3.30, ext: 7.6, h: 13 }, // West
    { angle: 4.00, ext: 8.4, h: 15 }, // North-West
    { angle: 5.45, ext: 8.4, h: 15 }  // North-East
  ];

  function chooseBark(x, y, z, dist, rEff, yRel) {
    const isSurface = dist >= rEff - 1.1;
    if (isSurface) {
      // Moisture moss on low buttress flutes
      if (yRel <= 2 && (x + z + y) % 5 === 0) {
        return mossBlock;
      }
      // Vertical furrowed strips of weathered heartwood
      const furrowStreak = Math.sin(x * 2.1 + z * 3.7 + y * 0.25);
      if (furrowStreak > 0.65) {
        return woodStripped;
      }
    }
    return woodLog;
  }

  // 1. Build Trunk & Buttress Roots conforming directly to terrain heightAt
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      const gh = Math.round(api.heightAt(x, z));
      const groundY = Math.max(0, Math.min(seatY + 12, seatY + gh));

      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      const angle = (Math.atan2(dz, dx) + Math.PI * 2) % (Math.PI * 2);

      // Build from local ground upwards to top of main trunk
      for (let y = groundY; y < seatY + 48; y++) {
        const yRel = y - seatY;
        const rTrunk = getTrunkRadius(yRel);

        let extra = 0;
        for (let i = 0; i < buttresses.length; i++) {
          const b = buttresses[i];
          if (yRel < b.h) {
            const vertFactor = Math.pow(Math.max(0, 1 - yRel / b.h), 1.6);
            const ad = angDiff(angle, b.angle);
            extra += b.ext * vertFactor * Math.exp(-Math.pow(ad / 0.35, 2));
          }
        }

        const furrow = 0.22 * Math.cos(12 * angle) + 0.15 * Math.sin(6 * angle + yRel * 0.4);
        const rEff = rTrunk + extra + furrow;

        if (dist <= rEff) {
          grid[x][y][z] = chooseBark(x, y, z, dist, rEff, yRel);
        }
      }
    }
  }

  // 2. Carve Hollow Walk-in Base Chamber & Chimney Flue
  for (let y = seatY + 1; y <= seatY + 6; y++) {
    const yRel = y - seatY;
    const rInt = 3.3 - 0.25 * Math.max(0, yRel - 2);
    for (let x = cx - 4; x <= cx + 4; x++) {
      for (let z = cz - 4; z <= cz + 4; z++) {
        const d = Math.sqrt((x - cx) ** 2 + (z - cz) ** 2);
        if (d < rInt) {
          grid[x][y][z] = null;
        }
      }
    }
  }

  // Narrow flue continuing upward for ambient top light
  for (let y = seatY + 7; y <= seatY + 14; y++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      for (let z = cz - 1; z <= cz + 1; z++) {
        if ((x - cx) ** 2 + (z - cz) ** 2 <= 1.5) {
          grid[x][y][z] = null;
        }
      }
    }
  }

  // Grand North Walk-In Doorway (North is -Z)
  for (let y = seatY + 1; y <= seatY + 3; y++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      for (let z = 6; z <= cz; z++) {
        grid[x][y][z] = null;
      }
    }
  }
  // Doorway arch top
  for (let z = 8; z <= cz - 1; z++) {
    grid[cx][seatY + 4][z] = null;
  }

  // Solid chamber floor and entry threshold
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let z = 6; z <= cz + 4; z++) {
      const d = Math.sqrt((x - cx) ** 2 + (z - cz) ** 2);
      if (d <= 3.8 || (Math.abs(x - cx) <= 1 && z <= cz)) {
        if (!grid[x][seatY][z]) {
          grid[x][seatY][z] = (d < 2.2) ? woodPlanks : woodStripped;
        }
      }
    }
  }

  // Natural wooden interior perimeter benches
  for (let x = cx - 3; x <= cx + 3; x++) {
    for (let z = cz - 3; z <= cz + 3; z++) {
      const d = Math.sqrt((x - cx) ** 2 + (z - cz) ** 2);
      if (d >= 2.3 && d <= 3.1 && grid[x][seatY + 1][z] === null && z >= cz - 1) {
        grid[x][seatY + 1][z] = woodSlab;
      }
    }
  }

  // 3. Draw Heavy Scaffold Branches
  function drawBranch(p0, p1, r0, r1) {
    const dist = Math.hypot(p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]);
    const steps = Math.max(12, Math.ceil(dist * 2.5));
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const px = p0[0] + t * (p1[0] - p0[0]);
      const py = p0[1] + t * (p1[1] - p0[1]);
      const pz = p0[2] + t * (p1[2] - p0[2]);
      const r = r0 + t * (r1 - r0);
      const ir = Math.ceil(r);

      for (let dx = -ir; dx <= ir; dx++) {
        for (let dy = -ir; dy <= ir; dy++) {
          for (let dz = -ir; dz <= ir; dz++) {
            if (dx * dx + dy * dy + dz * dz <= r * r) {
              const bx = Math.round(px + dx);
              const by = Math.round(py + dy);
              const bz = Math.round(pz + dz);
              if (bx >= 0 && bx < sizeX && by >= 0 && by < sizeY && bz >= 0 && bz < sizeZ) {
                grid[bx][by][bz] = (r < 1.3 && (dx + dy + dz) % 2 === 0) ? woodStripped : woodLog;
              }
            }
          }
        }
      }
    }
  }

  const scaffoldBranches = [
    // SE lower branch & fork
    { start: [cx, seatY + 31, cz], end: [cx + 9, seatY + 34, cz + 7], r0: 2.2, r1: 1.2 },
    { start: [cx + 6, seatY + 33, cz + 5], end: [cx + 10, seatY + 36, cz + 2], r0: 1.3, r1: 0.9 },
    // NW lower branch & fork
    { start: [cx, seatY + 34, cz], end: [cx - 9, seatY + 37, cz - 7], r0: 2.2, r1: 1.2 },
    { start: [cx - 5, seatY + 36, cz - 4], end: [cx - 9, seatY + 38, cz - 1], r0: 1.3, r1: 0.9 },
    // SW mid branch
    { start: [cx, seatY + 38, cz], end: [cx - 7, seatY + 41, cz + 7], r0: 2.0, r1: 1.1 },
    // NE mid branch
    { start: [cx, seatY + 40, cz], end: [cx + 8, seatY + 43, cz - 6], r0: 2.0, r1: 1.1 },
    // W upper branch
    { start: [cx, seatY + 43, cz], end: [cx - 6, seatY + 45, cz - 1], r0: 1.6, r1: 1.0 },
    // E upper branch
    { start: [cx, seatY + 44, cz], end: [cx + 6, seatY + 46, cz + 2], r0: 1.6, r1: 1.0 },
    // Crown spire
    { start: [cx, seatY + 44, cz], end: [cx, seatY + 52, cz], r0: 1.8, r1: 0.8 }
  ];

  for (let i = 0; i < scaffoldBranches.length; i++) {
    const b = scaffoldBranches[i];
    drawBranch(b.start, b.end, b.r0, b.r1);
  }

  // 4. Foliage Cloud Pads
  const foliagePads = [
    { center: [cx + 9, seatY + 34, cz + 7], rx: 4.2, ry: 2.0, rz: 4.2 },
    { center: [cx + 10, seatY + 36, cz + 2], rx: 3.5, ry: 1.8, rz: 3.5 },
    { center: [cx - 9, seatY + 37, cz - 7], rx: 4.2, ry: 2.0, rz: 4.2 },
    { center: [cx - 9, seatY + 38, cz - 1], rx: 3.5, ry: 1.8, rz: 3.5 },
    { center: [cx - 7, seatY + 41, cz + 7], rx: 4.0, ry: 2.0, rz: 4.0 },
    { center: [cx + 8, seatY + 43, cz - 6], rx: 4.0, ry: 2.0, rz: 4.0 },
    { center: [cx - 6, seatY + 45, cz - 1], rx: 3.5, ry: 1.8, rz: 3.5 },
    { center: [cx + 6, seatY + 46, cz + 2], rx: 3.5, ry: 1.8, rz: 3.5 },
    // Tiered apex crown
    { center: [cx, seatY + 47, cz], rx: 4.8, ry: 2.2, rz: 4.8 },
    { center: [cx, seatY + 50, cz], rx: 3.8, ry: 2.0, rz: 3.8 },
    { center: [cx, seatY + 53, cz], rx: 2.5, ry: 1.8, rz: 2.5 }
  ];

  for (let i = 0; i < foliagePads.length; i++) {
    const p = foliagePads[i];
    const minX = Math.max(0, Math.floor(p.center[0] - p.rx));
    const maxX = Math.min(sizeX - 1, Math.ceil(p.center[0] + p.rx));
    const minY = Math.max(0, Math.floor(p.center[1] - p.ry));
    const maxY = Math.min(sizeY - 1, Math.ceil(p.center[1] + p.ry));
    const minZ = Math.max(0, Math.floor(p.center[2] - p.rz));
    const maxZ = Math.min(sizeZ - 1, Math.ceil(p.center[2] + p.rz));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const qx = (x - p.center[0]) / p.rx;
          const qy = (y - p.center[1]) / p.ry;
          const qz = (z - p.center[2]) / p.rz;
          const distSq = qx * qx + qy * qy + qz * qz;
          if (distSq <= 1.0) {
            if (grid[x][y][z] === null) {
              grid[x][y][z] = leaves;
            }
          }
        }
      }
    }
  }

  // 5. Ancient Moss Drapes & Hanging Roots
  for (let x = 1; x < sizeX - 1; x++) {
    for (let z = 1; z < sizeZ - 1; z++) {
      for (let y = seatY + 25; y < sizeY - 2; y++) {
        if (grid[x][y][z] === leaves) {
          // Moss carpet on top surfaces
          if (grid[x][y + 1][z] === null && ((x * 7 + z * 11 + y) % 5 === 0)) {
            grid[x][y + 1][z] = mossCarpet;
          }
          // Hanging root tendrils beneath foliage underside
          if (grid[x][y - 1][z] === null && ((x * 13 + z * 17 + y) % 7 === 0)) {
            grid[x][y - 1][z] = hangingRoots;
            if (grid[x][y - 2][z] === null && ((x + z) % 3 === 0)) {
              grid[x][y - 2][z] = leaves;
            }
          }
        }
      }
    }
  }

  // 6. Emit Voxels Deterministically
  for (let y = 0; y < sizeY; y++) {
    for (let x = 0; x < sizeX; x++) {
      for (let z = 0; z < sizeZ; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Colossal Elder Redwood",
    seatY: seatY,
    anchors: {
      front: [cx, seatY + 1, 0],
      door: [cx, seatY + 1, 7],
      crown: [cx, seatY + 54, cz]
    },
    interiors: [
      {
        min: [cx - 3, seatY + 1, cz - 3],
        max: [cx + 3, seatY + 5, cz + 3],
        kind: "vault"
      }
    ]
  };
}

steam_log_derrick.source:
export const envelope = [19, 18, 19];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 4;

  // Grid buffer for deterministic assembly and solid connectivity
  const grid = Array.from({ length: sizeX }, () =>
    Array.from({ length: sizeY }, () =>
      Array.from({ length: sizeZ }, () => null)
    )
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      grid[x][y][z] = block;
    }
  }

  function formatBlock(base, states) {
    if (base.includes("[")) {
      const [name, existing] = base.slice(0, -1).split("[");
      return `${name}[${existing},${states}]`;
    }
    return `${base}[${states}]`;
  }

  // --- Theme Palettes & Fallbacks ---
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const roofSolid = api.theme?.roof?.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme?.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme?.roof?.slab || "minecraft:dark_oak_slab";

  // Formatted Wood & Masonry Blocks
  const logY = formatBlock(woodLog, "axis=y");
  const logZ = formatBlock(woodLog, "axis=z");
  const logX = formatBlock(woodLog, "axis=x");

  const stripY = formatBlock(woodStripped, "axis=y");
  const stripZ = formatBlock(woodStripped, "axis=z");
  const stripX = formatBlock(woodStripped, "axis=x");

  const slabBottom = formatBlock(woodSlab, "type=bottom");
  const slabTop = formatBlock(woodSlab, "type=top");

  const stairsN = formatBlock(woodStairs, "facing=north,half=bottom");
  const stairsS = formatBlock(woodStairs, "facing=south,half=bottom");
  const stairsE = formatBlock(woodStairs, "facing=east,half=bottom");
  const stairsW = formatBlock(woodStairs, "facing=west,half=bottom");

  const rStairsN = formatBlock(roofStairs, "facing=north,half=bottom");
  const rStairsS = formatBlock(roofStairs, "facing=south,half=bottom");
  const rStairsE = formatBlock(roofStairs, "facing=east,half=bottom");
  const rStairsW = formatBlock(roofStairs, "facing=west,half=bottom");

  const chainY = "minecraft:chain[axis=y]";
  const chainZ = "minecraft:chain[axis=z]";
  const chainX = "minecraft:chain[axis=x]";
  const ironBars = "minecraft:iron_bars";

  // =========================================================================
  // 1. Heavy Timber Yard Sills & Sub-Frame Deck (Y = 4)
  // =========================================================================

  // Longitudinal North-South Timber Sills
  for (const x of [4, 7, 9, 11, 14]) {
    for (let z = 2; z <= 16; z++) {
      set(x, 4, z, logZ);
    }
  }

  // Cross Sills (Sleepers)
  for (const z of [2, 4, 6, 8, 11, 14, 16]) {
    for (let x = 4; x <= 14; x++) {
      set(x, 4, z, logX);
    }
  }

  // Corner Anchor Extension Sills for Derrick Stiff-Legs
  for (let z = 15; z <= 17; z++) {
    set(2, 4, z, stonePrimary);
    set(3, 4, z, stonePrimary);
    set(15, 4, z, stonePrimary);
    set(16, 4, z, stonePrimary);
  }

  // Planking & Walkways on Yard Deck
  for (let x = 5; x <= 13; x++) {
    for (let z = 3; z <= 15; z++) {
      if (!grid[x][4][z]) {
        set(x, 4, z, woodPlanks);
      }
    }
  }

  // =========================================================================
  // 2. North Log Skid Ramp & Stacked Timber Storage (Z: 1 to 7, X: 4 to 14)
  // =========================================================================

  // Skid Ramp runners sloping down to ground at Z = 1
  for (let x = 4; x <= 14; x += 2) {
    set(x, 4, 1, stairsS);
  }
  for (let x = 5; x <= 13; x += 2) {
    set(x, 4, 1, slabBottom);
  }

  // Skid glide logs (stripped redwood skids)
  for (const x of [6, 8, 10, 12]) {
    for (let z = 2; z <= 7; z++) {
      set(x, 5, z, stripZ);
    }
  }

  // Tier 1 Harvested Redwood Logs (East-West trunks lying on skids)
  for (let x = 5; x <= 13; x++) {
    set(x, 5, 3, logX);
    set(x, 5, 5, logX);
    set(x, 5, 7, logX);
  }

  // Tier 2 Stacked Logs
  for (let x = 6; x <= 12; x++) {
    set(x, 6, 4, logX);
    set(x, 6, 6, logX);
  }

  // Heavy Iron Chain Binders holding log piles in place
  for (const x of [7, 11]) {
    set(x, 6, 3, chainY);
    set(x, 7, 4, chainZ);
    set(x, 7, 5, chainZ);
    set(x, 7, 6, chainZ);
    set(x, 6, 7, chainY);
  }

  // Chock wedges on log ends
  set(5, 6, 3, stairsE);
  set(13, 6, 3, stairsW);
  set(5, 6, 5, stairsE);
  set(13, 6, 5, stairsW);
  set(5, 6, 7, stairsE);
  set(13, 6, 7, stairsW);

  // =========================================================================
  // 3. Central Derrick Mast & Turntable Base (X: 8 to 10, Z: 8 to 10, Y: 4 to 16)
  // =========================================================================

  // Turntable Pivot Base
  for (let x = 8; x <= 10; x++) {
    for (let z = 8; z <= 10; z++) {
      set(x, 4, z, stonePrimary);
      set(x, 5, z, (x === 9 && z === 9) ? "minecraft:polished_deepslate" : slabTop);
    }
  }
  set(9, 5, 9, "minecraft:anvil[facing=north]");

  // Vertical Mast Spine (Center at 9, 9)
  for (let y = 5; y <= 16; y++) {
    set(9, y, 9, logY);
  }

  // Mast Side Columns & Lower Bracing (Y: 5 to 11)
  for (let y = 5; y <= 11; y++) {
    set(8, y, 9, logY);
    set(10, y, 9, logY);
  }

  // Mast Taper Bracing & Iron Collars
  for (let y = 12; y <= 15; y++) {
    set(8, y, 9, woodFence);
    set(10, y, 9, woodFence);
  }

  // Iron strapping bands on the mast
  set(9, 7, 8, ironBars);
  set(9, 7, 10, ironBars);
  set(9, 11, 8, ironBars);
  set(9, 11, 10, ironBars);
  set(9, 14, 8, ironBars);
  set(9, 14, 10, ironBars);

  // Inspection Ladder on South Mast Face
  for (let y = 6; y <= 14; y++) {
    set(9, y, 10, "minecraft:ladder[facing=south]");
  }

  // Mast Crown Head & Pulleys (Y: 16)
  set(9, 16, 9, "minecraft:anvil[facing=north]");
  set(9, 16, 8, ironBars);
  set(9, 16, 10, ironBars);
  set(8, 16, 9, ironBars);
  set(10, 16, 9, ironBars);

  // Mast Head Signal Lantern
  set(9, 15, 8, "minecraft:lantern[hanging=true]");

  // =========================================================================
  // 4. Stiff-Leg Diagonal Timber Braces (South-West & South-East)
  // =========================================================================

  // Massive corner anchor plinths
  for (let y = 4; y <= 5; y++) {
    set(3, y, 16, stonePrimary);
    set(3, y, 17, stoneAccent);
    set(2, y, 16, stoneAccent);
    set(15, y, 16, stonePrimary);
    set(15, y, 17, stoneAccent);
    set(16, y, 16, stoneAccent);
  }
  set(3, 6, 16, "minecraft:iron_bars");
  set(15, 6, 16, "minecraft:iron_bars");

  // South-West Diagonal Strut: from (9, 15, 9) down to (3, 5, 16)
  const swPath = [
    [8, 14, 10, stripY],
    [8, 13, 11, stripZ],
    [7, 12, 11, stripX],
    [7, 11, 12, stripZ],
    [6, 10, 12, stripX],
    [6, 9, 13, stripZ],
    [5, 8, 13, stripX],
    [5, 7, 14, stripZ],
    [4, 6, 14, stripX],
    [4, 5, 15, stripZ],
    [3, 5, 16, logY]
  ];
  for (const [x, y, z, block] of swPath) {
    set(x, y, z, block);
    // Reinforce stiff-leg with lower diagonal tie
    if (y >= 6 && y <= 13) {
      set(x, y - 1, z, woodFence);
    }
  }

  // South-East Diagonal Strut: from (9, 15, 9) down to (15, 5, 16)
  const sePath = [
    [10, 14, 10, stripY],
    [10, 13, 11, stripZ],
    [11, 12, 11, stripX],
    [11, 11, 12, stripZ],
    [12, 10, 12, stripX],
    [12, 9, 13, stripZ],
    [13, 8, 13, stripX],
    [13, 7, 14, stripZ],
    [14, 6, 14, stripX],
    [14, 5, 15, stripZ],
    [15, 5, 16, logY]
  ];
  for (const [x, y, z, block] of sePath) {
    set(x, y, z, block);
    if (y >= 6 && y <= 13) {
      set(x, y - 1, z, woodFence);
    }
  }

  // Steel Stay Tension Cables (Mast head to corner footings)
  set(9, 16, 10, chainZ);
  set(8, 15, 11, chainZ);
  set(10, 15, 11, chainZ);
  set(7, 14, 12, chainZ);
  set(11, 14, 12, chainZ);

  // =========================================================================
  // 5. Derrick Lattice Boom & Suspended Redwood Log Load
  // =========================================================================

  // Boom Heel Pivot at (9, 5, 8)
  set(9, 5, 8, logZ);
  set(8, 5, 8, ironBars);
  set(10, 5, 8, ironBars);

  // Boom Truss Spine reaching up and out to North
  const boomPoints = [
    [9, 6, 7, stripZ],
    [9, 7, 6, stripZ],
    [9, 8, 5, stripZ],
    [9, 9, 5, stripY],
    [9, 10, 4, stripZ],
    [9, 11, 3, stripZ],
    [9, 12, 3, stripY],
    [9, 13, 2, stripZ] // Boom Tip
  ];

  for (const [x, y, z, blk] of boomPoints) {
    set(x, y, z, blk);
    // Lattice side chords
    set(8, y, z, woodFence);
    set(10, y, z, woodFence);
  }

  // Topping Lift Rigging Cables (Mast head to Boom tip)
  set(9, 16, 8, chainZ);
  set(9, 15, 6, chainZ);
  set(9, 15, 5, chainZ);
  set(9, 14, 4, chainZ);
  set(9, 14, 3, chainZ);

  // Boom Tip Sheave Block
  set(9, 13, 2, "minecraft:anvil[facing=north]");
  set(9, 13, 1, ironBars);

  // Hoist Cable hanging down from Boom Tip to Hook
  for (let y = 12; y >= 9; y--) {
    set(9, y, 2, chainY);
  }

  // Heavy Steel Lifting Hook & Spreader Bar
  set(9, 9, 2, "minecraft:hopper[facing=down]");
  set(8, 9, 2, stripX);
  set(10, 9, 2, stripX);
  set(7, 9, 2, chainY);
  set(11, 9, 2, chainY);

  // Suspended Colossal Redwood Log (Held mid-air at Y=8, Z=2)
  for (let x = 6; x <= 12; x++) {
    const logBlock = (x === 6 || x === 12) ? stripX : logX;
    set(x, 8, 2, logBlock);
  }

  // Chain slings wrapped around suspended log
  set(7, 8, 1, chainZ);
  set(7, 8, 3, chainZ);
  set(7, 7, 2, chainX);
  set(11, 8, 1, chainZ);
  set(11, 8, 3, chainZ);
  set(11, 7, 2, chainX);

  // =========================================================================
  // 6. Steam Winch House ("Steam Donkey" Machinery Shed, Z: 11 to 16, X: 6 to 12)
  // =========================================================================

  // Machinery Bay Timber Platform
  for (let x = 6; x <= 12; x++) {
    for (let z = 11; z <= 16; z++) {
      set(x, 4, z, woodPlanks);
    }
  }

  // Steam Boiler Foundation (Fireproof masonry bed)
  for (let z = 12; z <= 14; z++) {
    set(6, 4, z, stonePrimary);
    set(7, 4, z, stonePrimary);
    set(8, 4, z, stonePrimary);
  }

  // --- Horizontal Fire-Tube Boiler ---
  // Firebox & Fuel Door at South End
  set(7, 5, 14, "minecraft:blast_furnace[facing=north]");
  set(6, 5, 14, "minecraft:coal_block"); // Fuel reserve box
  set(6, 6, 14, formatBlock(woodTrapdoor, "facing=north,half=bottom,open=false"));

  // Boiler Cylindrical Drum
  set(7, 5, 13, "minecraft:polished_basalt[axis=z]");
  set(7, 5, 12, "minecraft:polished_basalt[axis=z]");
  set(7, 6, 14, "minecraft:polished_basalt[axis=z]");
  set(7, 6, 13, "minecraft:polished_basalt[axis=z]");
  set(7, 6, 12, "minecraft:polished_basalt[axis=z]");
  set(7, 6, 11, stoneStairs); // Boiler front dome

  // Pressure Gauge & Safety Steam Valve
  set(7, 7, 13, "minecraft:lever[face=floor,facing=north]");
  set(8, 6, 13, "minecraft:tripwire_hook[facing=east]");

  // Water Feed Cauldron & Oil Barrel
  set(6, 5, 13, "minecraft:cauldron");
  set(6, 5, 12, "minecraft:barrel[facing=up]");

  // Tall Industrial Steam Smokestack (Venting up through roof)
  set(7, 7, 12, "minecraft:hopper[facing=down]");
  for (let y = 8; y <= 11; y++) {
    set(7, y, 12, stoneWall);
  }
  // Smoke plume from spark arrestor cap
  set(7, 12, 12, "minecraft:campfire[lit=true]");

  // --- Dual Winch Cable Drums ---
  // Main Hoist Drum (North Drum)
  set(10, 5, 12, stripX);
  set(11, 5, 12, stripX);
  set(10, 6, 12, chainX);
  set(11, 6, 12, chainX);

  // Boom Topping Drum (South Drum)
  set(10, 5, 14, stripX);
  set(11, 5, 14, stripX);
  set(10, 6, 14, chainX);
  set(11, 6, 14, chainX);

  // Winch Cast Iron Drive Gears & Friction Clutches
  set(12, 5, 12, ironBars);
  set(12, 6, 12, ironBars);
  set(12, 5, 14, ironBars);
  set(12, 6, 14, ironBars);

  // Cables running from winch drums toward the mast
  set(10, 7, 12, chainY);
  set(10, 8, 11, chainZ);
  set(9, 9, 10, chainZ);

  // Operator Controls & Levers
  set(9, 5, 13, "minecraft:lever[face=floor,facing=north]");
  set(9, 5, 14, "minecraft:lever[face=floor,facing=north]");
  set(9, 5, 15, stripY); // Operator stand

  // Maintenance Tool Station (Anvil & Tool Chest)
  set(12, 5, 15, "minecraft:anvil[facing=east]");
  set(12, 5, 16, woodPlanks);

  // --- Winch Shed Shelter Timber Framing & Roof ---
  // Vertical Shed Corner Posts (Y: 5 to 8)
  for (let y = 5; y <= 8; y++) {
    set(6, y, 11, logY);
    set(12, y, 11, logY);
    set(6, y, 16, logY);
    set(12, y, 16, logY);
  }

  // South Weatherboard Wall Panels
  for (let x = 7; x <= 11; x++) {
    set(x, 5, 16, woodPlanks);
    set(x, 6, 16, woodPlanks);
    set(x, 7, 16, formatBlock(woodTrapdoor, "facing=south,half=bottom,open=false"));
  }

  // West Wall Panels behind boiler
  for (let z = 12; z <= 15; z++) {
    set(6, 7, z, formatBlock(woodTrapdoor, "facing=west,half=bottom,open=false"));
  }

  // Rafter Beams (Y: 8)
  for (let x = 6; x <= 12; x++) {
    set(x, 8, 11, logX);
    set(x, 8, 16, logX);
  }
  for (let z = 11; z <= 16; z++) {
    set(6, 8, z, logZ);
    set(12, 8, z, logZ);
  }

  // Gable Timber Roof (Sloping North & South, Y: 8 to 9)
  for (let x = 5; x <= 13; x++) {
    // North eave & slope
    set(x, 8, 10, rStairsS);
    set(x, 9, 11, rStairsS);

    // Ridge
    set(x, 9, 12, roofSolid);
    set(x, 9, 13, roofSolid);
    set(x, 9, 14, roofSolid);

    // South slope & eave
    set(x, 9, 15, rStairsN);
    set(x, 8, 16, rStairsN);
    set(x, 8, 17, formatBlock(roofSlab, "type=bottom"));
  }

  // Winch Bay Work Lighting
  set(9, 7, 13, "minecraft:lantern[hanging=true]");
  set(7, 7, 15, "minecraft:lantern[hanging=true]");

  // =========================================================================
  // 7. Ground Conformance: Foundation Pilings, Cribbing & Hillside Skirts
  // =========================================================================

  // Key foundation pier locations under all sill grid intersections
  const pierColumns = [];
  for (const x of [4, 7, 9, 11, 14]) {
    for (const z of [2, 4, 6, 8, 11, 14, 16]) {
      pierColumns.push([x, z]);
    }
  }
  pierColumns.push([2, 16], [3, 16], [3, 17], [15, 16], [15, 17], [16, 16]);

  for (const [x, z] of pierColumns) {
    const groundH = Math.round(seatY + api.heightAt(x, z));
    const targetY = Math.max(0, Math.min(sizeY - 1, groundH));
    const pierBlock = (x <= 3 || x >= 15 || z >= 14) ? stonePrimary : logY;

    for (let y = 4; y >= targetY; y--) {
      set(x, y, z, pierBlock);
    }
  }

  // General ground-conformance sweep across all occupied structure columns
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      let lowestY = -1;
      for (let y = 0; y < sizeY; y++) {
        if (grid[x][y][z] !== null) {
          lowestY = y;
          break;
        }
      }

      if (lowestY !== -1) {
        const localGround = Math.round(seatY + api.heightAt(x, z));
        const targetGroundY = Math.max(0, Math.min(sizeY - 1, localGround));

        // Downhill: structure is above ground; extend foundation down
        if (targetGroundY < lowestY) {
          const baseBlock = grid[x][lowestY][z];
          const isStoneBase = baseBlock.includes("stone") || baseBlock.includes("deepslate") || baseBlock.includes("cobble");
          const foundation = isStoneBase ? stonePrimary : (lowestY <= 4 ? logY : woodPlanks);

          for (let y = lowestY - 1; y >= targetGroundY; y--) {
            if (grid[x][y][z] === null) {
              set(x, y, z, foundation);
            }
          }
        }
        // Uphill: ground rises into structure; ensure solid seat
        else if (targetGroundY > lowestY && targetGroundY < sizeY) {
          for (let y = lowestY; y <= targetGroundY; y++) {
            if (grid[x][y][z] === null) {
              set(x, y, z, stonePrimary);
            }
          }
        }
      }
    }
  }

  // =========================================================================
  // 8. Flush Buffer to Output Stream
  // =========================================================================
  for (let y = 0; y < sizeY; y++) {
    for (let z = 0; z < sizeZ; z++) {
      for (let x = 0; x < sizeX; x++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "steam_log_derrick",
    seatY,
    anchors: {
      front: [9, seatY, 0],
      winch: [9, 5, 14],
      boom_tip: [9, 13, 2]
    }
  };
}

