export const envelope = [16, 10, 10];

export default function build(api) {
  const size = api.size;
  const seatY = 2;
  const rng = api.random;
  const instanceIndex = (api.instance ? api.instance.index : 0) % 8;

  // Theme palette extraction
  const themeWood = api.theme.wood || {};
  const themeStone = api.theme.stone || {};
  const themeGround = api.theme.ground || {};

  const plankBlock = themeWood.planks || "minecraft:spruce_planks";
  const logBase = (themeWood.log || "minecraft:spruce_log").split("[")[0];
  const strippedBase = (themeWood.stripped || themeWood.log || "minecraft:stripped_spruce_log").split("[")[0];
  const woodStairsBase = (themeWood.stairs || "minecraft:spruce_stairs").split("[")[0];
  const woodSlabBase = (themeWood.slab || "minecraft:spruce_slab").split("[")[0];
  const woodFence = themeWood.fence || "minecraft:spruce_fence";

  function getLog(axis) {
    return `${logBase}[axis=${axis || "x"}]`;
  }
  function getStripped(axis) {
    return `${strippedBase}[axis=${axis || "x"}]`;
  }
  function getStairs(facing, half, shape) {
    return `${woodStairsBase}[facing=${facing || "north"},half=${half || "bottom"},shape=${shape || "straight"}]`;
  }
  function getSlab(type) {
    return `${woodSlabBase}[type=${type || "bottom"}]`;
  }

  // Bounds-checked placement
  function setBlock(x, y, z, block) {
    if (x < 0 || x >= size[0] || y < 0 || y >= size[1] || z < 0 || z >= size[2]) return;
    api.set(x, y, z, block);
  }

  // Ground conforming column placement
  function placeGroundSupport(x, z, topY, block, foundationBlock) {
    const h = api.heightAt(x, z);
    const groundY = Math.max(0, seatY + Math.round(h));
    const effectiveTopY = Math.min(size[1] - 1, Math.max(topY, groundY));
    const clampedBottomY = Math.min(groundY, topY);
    for (let y = clampedBottomY; y <= effectiveTopY; y++) {
      setBlock(x, y, z, y === effectiveTopY ? block : (foundationBlock || block));
    }
  }

  // 1. Skidway bunk foundations and cradles
  const skidXPositions = [2, 7, 12];
  for (let i = 0; i < skidXPositions.length; i++) {
    const sx = skidXPositions[i];
    for (let sz = 1; sz <= 8; sz++) {
      placeGroundSupport(sx, sz, seatY, getLog("z"), themeGround.revetment || getLog("y"));
      placeGroundSupport(sx + 1, sz, seatY, getLog("z"), themeGround.revetment || getLog("y"));
    }
    // Wedge chocks wedged against the sides of the log
    setBlock(sx, seatY + 1, 2, getStairs("south", "bottom"));
    setBlock(sx + 1, seatY + 1, 2, getStairs("south", "bottom"));
    setBlock(sx, seatY + 1, 7, getStairs("north", "bottom"));
    setBlock(sx + 1, seatY + 1, 7, getStairs("north", "bottom"));

    // Vertical timber holding stakes
    placeGroundSupport(sx, 1, seatY + 2, woodFence, getLog("y"));
    placeGroundSupport(sx + 1, 1, seatY + 2, woodFence, getLog("y"));
    placeGroundSupport(sx, 8, seatY + 2, woodFence, getLog("y"));
    placeGroundSupport(sx + 1, 8, seatY + 2, woodFence, getLog("y"));
  }

  // Longitudinal skid runners along base
  for (let x = 0; x < size[0]; x++) {
    placeGroundSupport(x, 3, seatY, getLog("x"), themeGround.revetment || getLog("y"));
    placeGroundSupport(x, 6, seatY, getLog("x"), themeGround.revetment || getLog("y"));
  }

  // 2. Colossal Redwood Trunk Geometry
  const xMin = 1;
  const xMax = 14;
  const cy = seatY + 3.2; // trunk center Y (~5.2)
  const cz = 4.5;         // trunk center Z
  const baseRadius = 2.45 + (instanceIndex % 3) * 0.12;
  const hasButtFlare = (instanceIndex === 0 || instanceIndex === 6);
  const isTapered = (instanceIndex === 2 || instanceIndex === 4);

  // Debarking pattern logic per instance
  function isBarkStripped(inst, x, y, z, angle, dy) {
    if (inst === 2) return true; // Heavily debarked flume log
    if (inst === 1 && dy > 0.4) return true; // Top peeled
    if (inst === 4 && (x >= 4 && x <= 11) && dy > 0.2) return true;
    if (inst === 7 && (angle > 0.2 && angle < 2.5)) return true;
    // Debarking spud score lines
    if ((x + Math.floor(angle * 2.0)) % 4 === 0) return true;
    return false;
  }

  // Specific cuts / notches / kerfs per instance
  function isCutOut(inst, x, y, z, dy, dz, distSq) {
    // Instance 0: Large felling undercut notch at butt end + bucking kerf
    if (inst === 0) {
      if (x >= 2 && x <= 3 && z <= cz && y <= cy && y >= cy - 2.0) return true;
      if (x === 9 && y >= cy + 0.4) return true;
    }
    // Instance 1: Radial splitting crevice at east cut face
    if (inst === 1) {
      if (x >= 12 && Math.abs(z - cz) <= 0.45 && y >= cy) return true;
    }
    // Instance 4: Deep quartering longitudinal crack
    if (inst === 4) {
      if (x >= 4 && x <= 13 && Math.abs(z - cz) <= 0.4 && y >= cy) return true;
    }
    // Instance 5: Bucked into two distinct logs with 1-block kerf gap
    if (inst === 5) {
      if (x === 8 && (y >= seatY + 1)) return true;
    }
    // Instance 6: Felling notch on south face
    if (inst === 6) {
      if (x === 3 && z >= cz && y <= cy) return true;
    }
    // Instance 7: Hollow heartwood fire scar cavity
    if (inst === 7) {
      if (x >= 2 && x <= 13 && distSq < 0.35) return true;
    }
    return false;
  }

  // Place trunk voxels
  for (let x = xMin; x <= xMax; x++) {
    let localRy = baseRadius;
    let localRz = baseRadius + 0.1;

    if (hasButtFlare && x <= 4) {
      const flare = (4 - x) * 0.35;
      localRy += flare * 0.4;
      localRz += flare * 0.6;
    }
    if (isTapered) {
      const taper = (x - xMin) / (xMax - xMin);
      localRy -= taper * 0.3;
      localRz -= taper * 0.3;
    }

    const yStart = Math.max(0, Math.floor(cy - localRy - 0.4));
    const yEnd = Math.min(size[1] - 1, Math.ceil(cy + localRy + 0.4));
    const zStart = Math.max(0, Math.floor(cz - localRz - 0.4));
    const zEnd = Math.min(size[2] - 1, Math.ceil(cz + localRz + 0.4));

    for (let y = yStart; y <= yEnd; y++) {
      for (let z = zStart; z <= zEnd; z++) {
        const dy = (y - cy) / localRy;
        const dz = (z - cz) / localRz;
        const distSq = dy * dy + dz * dz;

        if (distSq > 1.05) continue;

        if (isCutOut(instanceIndex, x, y, z, dy, dz, distSq)) {
          continue;
        }

        const isEndCut = (x === xMin || x === xMax);
        if (isEndCut) {
          // Crosscut end grain rings
          if (distSq < 0.22) {
            setBlock(x, y, z, plankBlock);
          } else if (distSq < 0.72) {
            setBlock(x, y, z, getStripped("x"));
          } else {
            setBlock(x, y, z, getLog("x"));
          }
        } else {
          // Lateral body
          const isOuter = distSq >= 0.62;
          if (!isOuter) {
            setBlock(x, y, z, getStripped("x"));
          } else {
            const angle = Math.atan2(dy, dz);
            if (isBarkStripped(instanceIndex, x, y, z, angle, dy)) {
              setBlock(x, y, z, getStripped("x"));
            } else {
              setBlock(x, y, z, getLog("x"));
            }
          }
        }
      }
    }
  }

  // 3. Instance-specific logging details, wedges, saws, and rigging
  const topLogY = Math.min(size[1] - 2, Math.ceil(cy + baseRadius));

  if (instanceIndex === 0) {
    // Two-man crosscut saw in kerf at x = 9
    for (let z = 2; z <= 7; z++) {
      setBlock(9, Math.round(cy + 0.6), z, "minecraft:iron_bars");
    }
    setBlock(9, Math.round(cy + 1.6), 2, woodFence);
    setBlock(9, Math.round(cy + 1.6), 7, woodFence);
    // Rigging chain
    setBlock(6, topLogY, Math.round(cz), "minecraft:chain[axis=z]");
  } else if (instanceIndex === 1) {
    // Steel splitting wedges driven into the split face
    setBlock(12, topLogY, Math.round(cz), "minecraft:anvil[facing=north]");
    setBlock(13, Math.round(cy + 0.8), Math.round(cz), "minecraft:stonecutter[facing=east]");
    setBlock(14, Math.round(cy), Math.round(cz), "minecraft:iron_bars");
    // Wooden splitting maul lying on top
    setBlock(10, topLogY + 1, Math.round(cz), plankBlock);
    setBlock(9, topLogY + 1, Math.round(cz), woodFence);
  } else if (instanceIndex === 2) {
    // Length measuring marks on peeled log
    setBlock(3, topLogY, Math.round(cz), getSlab("bottom"));
    setBlock(6, topLogY, Math.round(cz), getSlab("bottom"));
    setBlock(9, topLogY, Math.round(cz), getSlab("bottom"));
    setBlock(12, topLogY, Math.round(cz), getSlab("bottom"));
    // Cant hook stuck in side
    setBlock(5, Math.round(cy + 1), 7, woodFence);
    setBlock(5, Math.round(cy), 7, "minecraft:iron_bars");
    // Lantern on stake
    setBlock(13, seatY + 3, 1, woodFence);
    setBlock(13, seatY + 4, 1, "minecraft:lantern[hanging=false]");
  } else if (instanceIndex === 3) {
    // Large branch knuckle stub rising upward
    for (let y = topLogY; y <= Math.min(size[1] - 1, topLogY + 2); y++) {
      setBlock(6, y, Math.round(cz), getLog("y"));
      setBlock(6, y, Math.round(cz) - 1, getStripped("y"));
    }
    // Rigging chains
    setBlock(4, topLogY, Math.round(cz), "minecraft:chain[axis=z]");
    setBlock(11, topLogY, Math.round(cz), "minecraft:chain[axis=z]");
    setBlock(6, topLogY + 1, Math.round(cz) + 1, "minecraft:chain[axis=y]");
    setBlock(6, topLogY, Math.round(cz) + 1, "minecraft:lantern[hanging=true]");
  } else if (instanceIndex === 4) {
    // Multiple driven splitting wedges in a row
    setBlock(6, topLogY, Math.round(cz), "minecraft:iron_bars");
    setBlock(6, topLogY - 1, Math.round(cz), "minecraft:heavy_weighted_pressure_plate");
    setBlock(9, topLogY, Math.round(cz), "minecraft:iron_bars");
    setBlock(9, topLogY - 1, Math.round(cz), "minecraft:heavy_weighted_pressure_plate");
    setBlock(12, topLogY, Math.round(cz), "minecraft:anvil[facing=north]");
  } else if (instanceIndex === 5) {
    // Log dogs bridging the gap across the bucked sections
    setBlock(8, topLogY, Math.round(cz), "minecraft:iron_bars");
    setBlock(8, Math.round(cy), 2, "minecraft:iron_bars");
    setBlock(8, Math.round(cy), 7, "minecraft:iron_bars");
    // Two-man saw standing upright against stake
    setBlock(8, seatY + 1, 1, "minecraft:iron_bars");
    setBlock(8, seatY + 2, 1, "minecraft:iron_bars");
    setBlock(8, seatY + 3, 1, woodFence);
    // Axe stuck in top of section 1
    setBlock(5, topLogY + 1, Math.round(cz), woodFence);
  } else if (instanceIndex === 6) {
    // Heavy root flare lobes meeting the ground
    placeGroundSupport(1, 2, Math.round(cy), getLog("x"), getLog("y"));
    placeGroundSupport(1, 7, Math.round(cy), getLog("x"), getLog("y"));
    setBlock(2, topLogY + 1, Math.round(cz), getLog("x"));
    // Saw resting across wooden horses
    setBlock(9, seatY + 1, 1, woodFence);
    setBlock(12, seatY + 1, 1, woodFence);
    setBlock(10, seatY + 2, 1, "minecraft:iron_bars");
    setBlock(11, seatY + 2, 1, "minecraft:iron_bars");
  } else if (instanceIndex === 7) {
    // Internal hollow cavity cross-struts
    setBlock(6, Math.round(cy), Math.round(cz), woodFence);
    setBlock(9, Math.round(cy), Math.round(cz), woodFence);
    // Steel wedge driven at the solid rim
    setBlock(5, topLogY, Math.round(cz), "minecraft:anvil[facing=north]");
  }

  // 4. Sawdust / woodchip scatter around work areas
  const sawdustCoords = [
    [2, 0], [3, 0], [8, 0], [9, 0], [13, 0],
    [2, 9], [3, 9], [8, 9], [9, 9], [13, 9]
  ];
  for (let i = 0; i < sawdustCoords.length; i++) {
    const sx = sawdustCoords[i][0];
    const sz = sawdustCoords[i][1];
    const h = api.heightAt(sx, sz);
    const gy = Math.max(0, seatY + Math.round(h));
    if (gy < size[1]) {
      setBlock(sx, gy, sz, getSlab("bottom"));
    }
  }

  return {
    name: "felled_redwood_log",
